INSERT INTO public.case_template (template_id, case_id, version, title, synopsis, status, definition_schema_version, definition_scope, review_status, rules_version, rule_execution_version, content_hash, truth_json, accusation_options_json, scoring_policy_json, rules_json, public_knowledge_json, created_at, published_at, retired_at) VALUES ('70e037df-c6b0-4857-be26-4f69066c15c4', 'case_001', '2-slice', '停电之夜', '澄明研究所，案发当晚。21:25，负责人陆衡被发现死在档案室。走廊曾短暂停电，档案柜敞开。四名相关人员仍在所内。你受托核对现场记录，查明凶手、凶器、动机与作案经过。第一周仅开放档案室与副研究员沈砚；其余三人可以作为指控候选。', 'PUBLISHED', 2, 'week_one_slice', 'pending_human_review', 'w1-2', 'w1-slice-2', '5ac6cb383a8cb7698a7d4b38db09dee1dabaed9f39884c55fa2cc811d531d75c', '{"steps": ["P_ENTER", "P_ATTACK", "P_STAGE"], "motive": "M01", "weapon": "W01", "culprit": "NPC01", "explanation": "沈砚为阻止B17实验造假被移交审计，利用工程检修造成的走廊停电，于21:10进入档案室。21:12，他用桌上的铜镇纸袭击陆衡；随后取走B17原始记录、翻乱档案柜伪装失窃，21:16离开。门禁核对限制了到场人选，镇纸上的新鲜血印联系了行凶者与凶器，移交联和伤后翻柜痕迹说明动机与善后顺序。停电是周启的违规检修，并非沈砚制造；许岚隐瞒了私借档案，林澄保存了未经许可的实验副本，两人均未行凶。第一周只验证档案室内的核心过程；其余人物秘密与检修核验留在全案草稿。"}', '{"motives": [{"id": "M01", "label": "阻止实验造假被移交审计"}, {"id": "M02", "label": "掩盖私借B17副本被发现"}, {"id": "M03", "label": "掩盖违规检修造成的事故"}], "weapons": [{"id": "W01", "label": "铜镇纸"}, {"id": "W02", "label": "裁纸刀"}, {"id": "W03", "label": "电缆"}], "suspects": [{"id": "NPC01", "label": "沈砚 · 副研究员"}, {"id": "NPC02", "label": "许岚 · 档案管理员"}, {"id": "NPC03", "label": "周启 · 值班工程师"}, {"id": "NPC04", "label": "林澄 · 研究助理"}], "process_steps": [{"id": "P_ATTACK", "label": "用铜镇纸袭击陆衡"}, {"id": "P_CUT_POWER", "label": "故意切断电源制造黑暗"}, {"id": "P_STAGE", "label": "取走原始记录并翻乱档案柜伪装失窃"}, {"id": "P_ENTER", "label": "停电期间进入档案室"}, {"id": "P_SEARCH_FIRST", "label": "先翻柜找记录，被陆衡撞见后行凶"}]}', '{"criteria": [{"id": "C_CULPRIT", "kind": "culprit", "label": "凶手", "points": 30, "step_id": null, "explanation": "行凶者为沈砚；选错凶手时总类别直接判错。", "evidence_ids": []}, {"id": "C_WEAPON", "kind": "weapon", "label": "凶器", "points": 15, "step_id": null, "explanation": "致命伤对应铜镇纸。", "evidence_ids": []}, {"id": "C_MOTIVE", "kind": "motive", "label": "动机", "points": 15, "step_id": null, "explanation": "沈砚试图阻止实验造假进入审计。", "evidence_ids": []}, {"id": "C_PROCESS", "kind": "process", "label": "过程顺序", "points": 15, "step_id": null, "explanation": "必须恰好按进入、袭击、伪装失窃的顺序选择步骤。", "evidence_ids": []}, {"id": "C_ENTRY", "kind": "support", "label": "到场依据", "points": 10, "step_id": "P_ENTER", "explanation": "进入步骤必须关联本次引用的E01备用门禁记录。", "evidence_ids": ["E01"]}, {"id": "C_ATTACK", "kind": "support", "label": "袭击依据", "points": 10, "step_id": "P_ATTACK", "explanation": "袭击步骤必须关联本次引用的E02镇纸与现场检验单。", "evidence_ids": ["E02"]}, {"id": "C_STAGE", "kind": "support", "label": "善后依据", "points": 5, "step_id": "P_STAGE", "explanation": "伪装步骤必须关联本次引用的E03移交联及伤后翻柜痕迹。", "evidence_ids": ["E03"]}], "correct_min": 85, "partial_min": 30, "process_order": "exact", "wrong_culprit_is_wrong": true}', '{"interrogation": {"topics": [{"id": "Q01", "label": "档案室丢了什么？", "reply": "柜子翻成那样，B17的原件肯定是被偷了。", "npc_id": "NPC01", "knowledge_id": "K03"}], "evade_after": 2, "evade_reply": "你一直拿不相干的东西来问我。我现在不想再谈了。", "contradictions": [{"id": "C01", "reply": "……我是猜的。柜子都被翻开了，丢的总归是要紧的东西。", "trust": 0, "npc_id": "NPC01", "pressure": 15, "evidence_id": "E03", "explanation": "缺失清单是核对封存卷宗后才确定的，此前没有对外公布；沈砚却已经说出丢的是B17原件。", "knowledge_id": "K03"}], "irrelevant_reply": "你到底想说什么？这和我有什么关系？", "irrelevant_trust": -5}, "present_effects": [{"trust": -5, "pressure": 25, "evidence_id": "E01", "lie_rule_id": "L01"}, {"trust": 0, "pressure": 25, "evidence_id": "E03", "lie_rule_id": "L01"}]}', '[{"id": "K01", "content": "沈砚负责B17实验组，平时有权限进入档案室。", "known_by": ["NPC01", "NPC02", "NPC03", "NPC04"], "disclosure": "PUBLIC"}]', '2026-11-01 15:31:14.977368+00', '2026-11-01 15:31:14.977368+00', NULL);
