INSERT INTO public.character_secret (template_id, secret_id, character_id, content, known_by_json, assertion_kind, initial_credibility, disclosure) VALUES ('70e037df-c6b0-4857-be26-4f69066c15c4', 'K02', 'NPC01', '沈砚承认21:10至21:16进入过档案室；此条只记录到场证词，不是杀人招供。', '["NPC01"]', 'TESTIMONY', 'UNVERIFIED', 'ADMITTED');
INSERT INTO public.character_secret (template_id, secret_id, character_id, content, known_by_json, assertion_kind, initial_credibility, disclosure) VALUES ('70e037df-c6b0-4857-be26-4f69066c15c4', 'K03', 'NPC01', '沈砚断言档案室丢的是B17原件：“柜子翻成那样，B17的原件肯定是被偷了。”此条只记录他的说法。', '["NPC01"]', 'TESTIMONY', 'UNVERIFIED', 'ASKED');
INSERT INTO public.scene (template_id, scene_id, name, description, sort_order, actions_json) VALUES ('70e037df-c6b0-4857-be26-4f69066c15c4', 'S01', '档案室', '桌面散着纸页，一枚铜镇纸留在地毯上。门旁的备用终端仍亮着，封存卷宗等待核对。', 0, '[{"id": "A01", "label": "查看备用门禁终端", "evidence_id": "E01"}, {"id": "A02", "label": "检查桌边与现场检验袋", "evidence_id": "E02"}, {"id": "A03", "label": "核对封存卷宗", "evidence_id": "E03"}]');
INSERT INTO public.evidence (template_id, evidence_id, name, content, source_label, source_type, source_scene_id, source_character_id, initial_credibility, sort_order) VALUES ('70e037df-c6b0-4857-be26-4f69066c15c4', 'E01', '备用门禁记录', '独立电池供电的终端保留了21:10沈砚进入、21:16离开档案室的刷卡与人脸核验记录。20:55至21:25，除室内的陆衡外没有其他人进出。现场人员已比对身份、终端校时记录和备用供电状态；记录证明到场，不单独证明杀人。', '档案室备用终端与现场核验单', 'SCENE', 'S01', NULL, 'VERIFIED', 0);
INSERT INTO public.evidence (template_id, evidence_id, name, content, source_label, source_type, source_scene_id, source_character_id, initial_credibility, sort_order) VALUES ('70e037df-c6b0-4857-be26-4f69066c15c4', 'E02', '铜镇纸与现场检验单', '铜镇纸的打击面残留陆衡的血迹，形状与致命伤吻合；握持面的新鲜血印与沈砚指纹匹配。桌角还发现沾血的撕裂手套片。检验单明确这些是本次现场检验的结论，不能仅凭一枚日常指纹认定行凶。', '现场物证袋与签名检验单', 'SCENE', 'S01', NULL, 'VERIFIED', 1);
INSERT INTO public.evidence (template_id, evidence_id, name, content, source_label, source_type, source_scene_id, source_character_id, initial_credibility, sort_order) VALUES ('70e037df-c6b0-4857-be26-4f69066c15c4', 'E03', '审计移交联与翻柜痕迹', '按门禁时段与物证编号核对后，卷宗显示：陆衡20:55签署移交单，次日上午将提交沈砚负责的B17实验原始记录，追查数据造假。柜中只缺B17原件，现金和其他卷宗未动；这份缺失清单是本次核对才确定的，此前没有对外公布。抽屉内侧及B17纸套上的同源血迹说明翻找发生在陆衡受伤之后。封存的移交联副本未被取走。', '封存卷宗、签名移交联副本和现场痕迹核对单', 'SCENE', 'S01', NULL, 'VERIFIED', 2);
INSERT INTO public.evidence_dependency (template_id, evidence_id, dependency_mode, required_evidence_id) VALUES ('70e037df-c6b0-4857-be26-4f69066c15c4', 'E03', 'ALL', 'E01');
